/**
 * Trustpilot's star.
 *
 * It takes the colour of the text around it, the way every other mark here
 * does, so a row in a menu draws it in the same muted ink as its neighbours
 * and answers a pointer in the same motion. Where the issued green is wanted,
 * the surface says so: `data-mark` is what a stylesheet reaches it by.
 *
 * Its own box is wider than the drafting grid, so the viewBox carries the
 * artwork's own numbers rather than being redrawn on twenty-four units.
 */
export function MarkTrustpilot(props) {
  return (
    <svg
      viewBox="0 0 271.3 258"
      fill="currentColor"
      data-mark="trustpilot"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      <path d="M271.3 98.6H167.7L135.7 0l-32.1 98.6L0 98.5l83.9 61L51.8 258l83.9-60.9 83.8 60.9-32-98.5 83.8-60.9z" />
    </svg>
  )
}

/**
 * Google's G.
 *
 * The issued mark is four colours, and a menu row that draws it in four while
 * its neighbours hold one colour reads as an advertisement sitting in a list.
 * So the single-colour mark Google publishes for exactly that case is the one
 * here, and `data-mark` is what a stylesheet reaches to give it back its blue
 * where a row wants it.
 */
export function MarkGoogle(props) {
  return (
    <svg {...BASE} data-mark="google" {...props}>
      <path d="M12.48 10.92v3.28h7.84c-.24 1.84-.853 3.187-1.787 4.133-1.147 1.147-2.933 2.4-6.053 2.4-4.827 0-8.6-3.893-8.6-8.72s3.773-8.72 8.6-8.72c2.6 0 4.507 1.027 5.907 2.347l2.307-2.307C18.747 1.44 16.133 0 12.48 0 5.867 0 .307 5.387.307 12s5.56 12 12.173 12c3.573 0 6.267-1.173 8.373-3.36 2.16-2.16 2.84-5.213 2.84-7.667 0-.76-.053-1.467-.173-2.053H12.48z" />
    </svg>
  )
}

