/**
 * The BBB torch.
 *
 * The seal BBB issues is a fixed piece of artwork with its own lettering and
 * its own ground, and it is the right thing in the footer, where there is room
 * to read it. It is the wrong thing in a menu row twenty pixels tall: at that
 * size the lettering is a smudge and the ground is a white rectangle sitting in
 * a column of glyphs. So the row draws the torch alone, on the same box the
 * other network marks are drawn on, and takes its colour from the text around
 * it the way they do.
 */
export function MarkBbb(props) {
  return (
    <svg {...BASE} data-mark="bbb" {...props}>
      <path d="M12 1.8c2.7 3 4.4 5.3 4.4 7.7a4.4 4.4 0 0 1-8.8 0c0-1.1.4-2 1.1-3 .2 1 .8 1.7 1.7 1.9-.6-2.4.3-4.6 1.6-6.6zM8 14.6h8l-1.1 2.4H9.1L8 14.6zm2.3 3.3h3.4l.7 4.3H9.6l.7-4.3z" />
    </svg>
  )
}
